      "name": "Normal Stress ($\text{at distance } y$)",
      "expression": "σ = My/I",
      "variables": "M = bending moment at the section; I = second moment of area of the cross-section about the neutral axis; y = distance from the neutral axis."
    },
    {
      "name": "Section Modulus",
      "expression": "Z = I/c",
      "variables": "I = second moment of area; c = distance to the extreme fibre."
    },
    {
      "name": "Maximum Stress",
      "expression": "σmax = M/Z",
      "variables": "M = bending moment; Z = section modulus."
    },
    {
      "name": "Maximum Bending Moment (Simply Supported Beam with Uniform Load)",
      "expression": "M_{max} = wL^2/8",
      "variables": "w = uniformly distributed load; L = span."
    },
    {
      "name": "Serviceability Limit (Floor Beams)",
      "expression": "Deflection Limit = Span/360",
      "variables": "Span = length of the beam."
    }
